/* Header and page share one centered column, so wide screens do not split the page to the edges. */
.site-header,
.page {
  max-width: 1152px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 24px;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 28px;
}

.site-nav a {
  text-decoration: none;
}

/* Two columns: pitch and routes on the left, the booking form on the right across both rows. */
.page {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  column-gap: 64px;
  row-gap: 48px;
  align-items: start;
  padding-top: 48px;
  padding-bottom: 64px;
}

.hero {
  max-width: 600px;
}

.search {
  grid-column: 2;
  grid-row: 1 / span 2;
  padding: 22px;
  border: 1px solid #dfe3e0;
  border-radius: 8px;
  background: #ffffff;
}

.routes {
  grid-column: 1;
}

h1 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.2;
  color: #26302f;
}

.lead {
  margin: 0;
  font-size: 20px;
  line-height: 1.5;
}

.search-title {
  margin-bottom: 14px;
  font-weight: 500;
}

.search label {
  display: block;
  margin-bottom: 12px;
  font-size: 14px;
  color: #5f6968;
}

.search select,
.search input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border: 1px solid #8a9491;
  border-radius: 6px;
  background: #ffffff;
  font: inherit;
  font-size: 16px;
  color: #26302f;
}

.search button {
  width: 100%;
  margin-top: 6px;
  padding: 11px;
  border: 0;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;
  font: inherit;
  font-weight: 500;
}

h2 {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
}

.routes ul {
  max-width: 600px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.routes li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 0;
  border-top: 1px solid #dfe3e0;
  color: #5f6968;
}

.route-name {
  color: #26302f;
}

/* Below this width the two columns stack: pitch, form, then routes. */
@media (max-width: 860px) {
  .page {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 40px;
  }

  .search,
  .routes {
    grid-column: 1;
    grid-row: auto;
  }

  /* Stacked blocks take the full column, so their right edge meets the nav's. */
  .hero,
  .routes ul {
    max-width: none;
  }
}

/* Phone: narrower margins, nav on its own row under the logo, smaller headline. */
@media (max-width: 560px) {
  .site-header,
  .page {
    padding-left: 20px;
    padding-right: 20px;
  }

  .site-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .site-nav {
    gap: 20px;
  }

  .page {
    padding-top: 24px;
  }

  h1 {
    font-size: 32px;
  }
}

